:root {
  --bg: #0f172a;
  --bg-soft: #111827;
  --surface: #1f2937;
  --surface-2: #243244;
  --border: #334155;
  --text: #e5e7eb;
  --muted: #94a3b8;
  --brand: #7c3aed;
  --brand-2: #06b6d4;
  --danger: #ef4444;
  --success: #10b981;
  --ring: rgba(124, 58, 237, 0.35);
}

html, body {
  min-height: 100%;
}

body {
  margin: 0;
  color: var(--text);
  background: linear-gradient(180deg, #0b1120 0%, var(--bg) 50%, #0b1020 100%);
  background-attachment: fixed;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

* {
  box-sizing: border-box;
}

button, [role="button"] {
  transition: transform 160ms ease, background-color 160ms ease, border-color 160ms ease, box-shadow 160ms ease, opacity 160ms ease;
}

button:hover, [role="button"]:hover {
  transform: translateY(-1px);
}

.card, .panel, .item-card, .listing-card {
  background: rgba(31, 41, 55, 0.82);
  border: 1px solid rgba(51, 65, 85, 0.85);
  box-shadow: 0 10px 30px rgba(2, 6, 23, 0.25);
  transition: transform 160ms ease, border-color 160ms ease, box-shadow 160ms ease, background-color 160ms ease;
}

.card:hover, .panel:hover, .item-card:hover, .listing-card:hover {
  border-color: rgba(124, 58, 237, 0.45);
  box-shadow: 0 14px 34px rgba(2, 6, 23, 0.34);
}

input, textarea, select {
  background-color: #0f172a;
  color: #e5e7eb;
  border: 1px solid var(--border);
  transition: border-color 160ms ease, box-shadow 160ms ease, background-color 160ms ease, color 160ms ease;
}

input::placeholder, textarea::placeholder {
  color: #64748b;
}

input:focus, textarea:focus, select:focus {
  outline: none;
  border-color: var(--brand);
  box-shadow: 0 0 0 4px var(--ring);
}

.view-enter {
  animation: viewFadeIn 220ms ease-out both;
}

@keyframes viewFadeIn {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

table {
  width: 100%;
  border-collapse: collapse;
  color: var(--text);
  background: rgba(17, 24, 39, 0.55);
  border: 1px solid rgba(51, 65, 85, 0.9);
  overflow: hidden;
}

th, td {
  padding: 0.75rem 0.875rem;
  border-bottom: 1px solid rgba(51, 65, 85, 0.75);
  text-align: left;
  vertical-align: middle;
}

th {
  color: #cbd5e1;
  font-weight: 600;
  background: rgba(15, 23, 42, 0.8);
}

tbody tr:hover {
  background: rgba(124, 58, 237, 0.08);
}

a {
  color: #93c5fd;
  transition: color 160ms ease, opacity 160ms ease;
}

a:hover {
  color: #c4b5fd;
}

::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

::-webkit-scrollbar-track {
  background: #0b1120;
}

::-webkit-scrollbar-thumb {
  background: #334155;
  border-radius: 999px;
}

::-webkit-scrollbar-thumb:hover {
  background: #475569;
}

#login-view, #app-view {
  max-width: 100%;
}

.container, .content, .main, .shell, .dashboard {
  max-width: 100%;
}

img, svg, video, canvas {
  max-width: 100%;
  height: auto;
}

(function () {
  const AUTH_KEY = "app:auth";
  const ENTITIES_KEY = "app:entities";
  const DEMO_EMAIL = "demo@example.com";
  const DEMO_PASSWORD = "demo";

  const $ = (sel) => document.querySelector(sel);

  const api = {
    list() {
      try {
        return JSON.parse(localStorage.getItem(ENTITIES_KEY) || "[]");
      } catch {
        return [];
      }
    },
    create(obj) {
      const item = {
        id: crypto.randomUUID(),
        createdAt: new Date().toISOString(),
        ...obj
      };
      const arr = api.list();
      arr.push(item);
      localStorage.setItem(ENTITIES_KEY, JSON.stringify(arr));
      return item;
    },
    remove(id) {
      const arr = api.list().filter((x) => x.id !== id);
      localStorage.setItem(ENTITIES_KEY, JSON.stringify(arr));
    }
  };

  function seedEntities() {
    const current = api.list();
    if (current.length) return;
    const seeds = [
      {
        type: "Lead",
        title: "Maya Chen",
        status: "New",
        amount: 0,
        property: "Downtown condo tour",
        date: "2026-07-08",
        notes: "Open house follow-up"
      },
      {
        type: "Showing",
        title: "1208 Maple Ave",
        status: "Scheduled",
        amount: 850000,
        property: "3BR single-family home",
        date: "2026-07-06",
        notes: "Buyer: Jordan"
      },
      {
        type: "Offer",
        title: "Riverside townhouse",
        status: "Negotiating",
        amount: 1250000,
        property: "Live offer",
        date: "2026-07-05",
        notes: "Counteroffer pending"
      },
      {
        type: "Listing",
        title: "47 Harbor View Dr",
        status: "Active",
        amount: 1795000,
        property: "Luxury waterfront listing",
        date: "2026-07-09",
        notes: "Photography complete"
      }
    ];
    localStorage.setItem(ENTITIES_KEY, JSON.stringify(seeds.map((s) => ({
      id: crypto.randomUUID(),
      createdAt: new Date().toISOString(),
      ...s
    }))));
  }

  function setView(isAuthed) {
    const loginView = $("#login-view");
    const appView = $("#app-view");
    if (loginView) loginView.style.display = isAuthed ? "none" : "";
    if (appView) appView.style.display = isAuthed ? "" : "none";
  }

  function getAuth() {
    try {
      return JSON.parse(localStorage.getItem(AUTH_KEY) || "null");
    } catch {
      return null;
    }
  }

  function renderKpis() {
    const strip = $("#kpi-strip");
    if (!strip) return;

    const items = api.list();
    const total = items.length;
    const active = items.filter((x) => String(x.status).toLowerCase() === "active").length;
    const scheduled = items.filter((x) => String(x.status).toLowerCase() === "scheduled").length;
    const negotiating = items.filter((x) => String(x.status).toLowerCase() === "negotiating").length;
    const pipelineValue = items.reduce((sum, x) => sum + (Number(x.amount) || 0), 0);

    strip.innerHTML = `
      <div class="kpi"><strong>${total}</strong><span>Total items</span></div>
      <div class="kpi"><strong>${active}</strong><span>Active listings</span></div>
      <div class="kpi"><strong>${scheduled}</strong><span>Scheduled showings</span></div>
      <div class="kpi"><strong>${negotiating}</strong><span>Negotiations</span></div>
      <div class="kpi"><strong>$${pipelineValue.toLocaleString()}</strong><span>Pipeline value</span></div>
    `;
  }

  function renderList() {
    const host = $("#entity-list");
    if (!host) return;
    const items = api.list();

    if (!items.length) {
      host.innerHTML = "<p>No pipeline items yet.</p>";
      return;
    }

    const rows = items
      .slice()
      .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
      .map(
        (x) => `
        <tr>
          <td>${escapeHtml(x.type || "")}</td>
          <td>${escapeHtml(x.title || "")}</td>
          <td>${escapeHtml(x.status || "")}</td>
          <td>${escapeHtml(x.property || "")}</td>
          <td>${formatMoney(x.amount)}</td>
          <td>${escapeHtml(x.date || "")}</td>
          <td>${escapeHtml(x.notes || "")}</td>
          <td><button type="button" data-delete-id="${x.id}">Delete</button></td>
        </tr>`
      )
      .join("");

    host.innerHTML = `
      <table>
        <thead>
          <tr>
            <th>Type</th>
            <th>Title</th>
            <th>Status</th>
            <th>Property</th>
            <th>Amount</th>
            <th>Date</th>
            <th>Notes</th>
            <th></th>
          </tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
    `;

    host.querySelectorAll("[data-delete-id]").forEach((btn) => {
      btn.addEventListener("click", () => {
        api.remove(btn.getAttribute("data-delete-id"));
        renderList();
        renderKpis();
      });
    });
  }

  function formatMoney(value) {
    const n = Number(value);
    if (!Number.isFinite(n) || n === 0) return "—";
    return `$${n.toLocaleString()}`;
  }

  function escapeHtml(str) {
    return String(str)
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#39;");
  }

  function wireAuth() {
    const btn = $("#login-btn");
    const emailInput = $("#login-email");
    const passwordInput = $("#login-password");
    const error = $("#login-error");
    if (!btn || !emailInput || !passwordInput) return;

    btn.addEventListener("click", () => {
      const email = emailInput.value.trim();
      const password = passwordInput.value;
      if (email === DEMO_EMAIL && password === DEMO_PASSWORD) {
        localStorage.setItem(
          AUTH_KEY,
          JSON.stringify({ email, loggedAt: new Date().toISOString() })
        );
        if (error) error.textContent = "";
        setView(true);
        renderKpis();
        renderList();
      } else if (error) {
        error.textContent = "Invalid demo credentials.";
      }
    });
  }

  function wireLogout() {
    const btn = $("#logout-btn");
    if (!btn) return;
    btn.addEventListener("click", () => {
      localStorage.removeItem(AUTH_KEY);
      location.reload();
    });
  }

  function wireCreateForm() {
    const form = $("#create-form");
    if (!form) return;
    form.addEventListener("submit", (e) => {
      e.preventDefault();
      const fd = new FormData(form);
      const obj = {
        type: String(fd.get("type") || "").trim() || "Lead",
        title: String(fd.get("title") || "").trim(),
        status: String(fd.get("status") || "").trim() || "New",
        property: String(fd.get("property") || "").trim(),
        amount: Number(fd.get("amount") || 0),
        date: String(fd.get("date") || "").trim(),
        notes: String(fd.get("notes") || "").trim()
      };
      api.create(obj);
      form.reset();
      renderList();
      renderKpis();
    });
  }

  document.addEventListener("DOMContentLoaded", () => {
    seedEntities();
    wireAuth();
    wireLogout();
    wireCreateForm();

    const authed = !!getAuth();
    setView(authed);
    if (authed) {
      renderKpis();
      renderList();
    }

    console.info("App ready · vanilla SPA · swap localStorage for backend/server.py to ship");
  });
})();

from datetime import datetime, timezone
from typing import Any, Dict, List, Optional
from uuid import uuid4

from fastapi import Depends, FastAPI, Header, HTTPException, Response, status
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, EmailStr, Field

app = FastAPI(title="Real Estate CRM API", version="1.0.0")

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

DEMO_EMAIL = "demo@example.com"
DEMO_PASSWORD = "demo"
API_VERSION = "1.0.0"

# In-memory stores for MVP/demo use.
# A real database (PostgreSQL, DynamoDB, etc.) would replace these dicts.
tokens: Dict[str, Dict[str, Any]] = {}
entities: Dict[str, Dict[str, Any]] = {}


def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


class User(BaseModel):
    id: str
    email: EmailStr
    name: str = "Demo Agent"
    role: str = "agent"


class LoginReq(BaseModel):
    email: EmailStr
    password: str = Field(min_length=1)


class LoginResp(BaseModel):
    token: str
    user: User


class EntityBase(BaseModel):
    title: str
    amount: Optional[float] = None
    type: Optional[str] = None
    status: Optional[str] = None
    notes: Optional[str] = None
    metadata: Dict[str, Any] = Field(default_factory=dict)


class EntityCreate(EntityBase):
    pass


class Entity(EntityBase):
    id: str
    createdAt: str
    updatedAt: str


class HealthResp(BaseModel):
    status: str
    version: str


def demo_user() -> User:
    return User(id="demo-user", email=DEMO_EMAIL, name="Demo Agent", role="agent")


def get_current_user(authorization: Optional[str] = Header(default=None)) -> User:
    if not authorization:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Missing Authorization header")
    if not authorization.startswith("Bearer "):
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid Authorization header")
    token = authorization.removeprefix("Bearer ").strip()
    user = tokens.get(token)
    if not user:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid or expired token")
    return User(**user)


@app.post("/api/auth/login", response_model=LoginResp)
def login(req: LoginReq) -> LoginResp:
    if req.email.lower() != DEMO_EMAIL or req.password != DEMO_PASSWORD:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid credentials")
    token = uuid4().hex
    user = demo_user()
    tokens[token] = user.model_dump()
    return LoginResp(token=token, user=user)


@app.get("/api/auth/me", response_model=User)
def me(user: User = Depends(get_current_user)) -> User:
    return user


@app.get("/api/entities", response_model=List[Entity])
def list_entities(user: User = Depends(get_current_user)) -> List[Entity]:
    return [Entity(**entity) for entity in sorted(entities.values(), key=lambda x: x["createdAt"], reverse=True)]


@app.post("/api/entities", response_model=Entity)
def create_entity(payload: EntityCreate, user: User = Depends(get_current_user)) -> Entity:
    entity_id = uuid4().hex
    entity = Entity(
        id=entity_id,
        createdAt=now_iso(),
        updatedAt=now_iso(),
        **payload.model_dump(),
    )
    entities[entity_id] = entity.model_dump()
    return entity


@app.delete("/api/entities")
def delete_entity(id: str, user: User = Depends(get_current_user)) -> Response:
    if id not in entities:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Entity not found")
    del entities[id]
    return Response(status_code=status.HTTP_204_NO_CONTENT)


@app.get("/api/health", response_model=HealthResp)
def health() -> HealthResp:
    return HealthResp(status="ok", version=API_VERSION)
